ALTER TABLE noctis_v2.jobs ADD COLUMN created_at timestamptz NOT NULL DEFAULT clock_timestamp();
ALTER TABLE noctis_v2.sources ADD COLUMN poll_after timestamptz NOT NULL DEFAULT clock_timestamp();
ALTER TABLE noctis_v2.outbox ADD COLUMN policy_version text,ADD COLUMN blocked_reason text;
ALTER TABLE noctis_v2.outbox DROP CONSTRAINT outbox_state_check;
ALTER TABLE noctis_v2.outbox ADD CHECK(state IN('queued','sending','delivered','uncertain','blocked','cancelled'));
CREATE TABLE noctis_v2.domain_audit(id uuid PRIMARY KEY,actor text NOT NULL,action text NOT NULL,result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
ALTER TABLE noctis_v2.observations ADD COLUMN source_deleted boolean NOT NULL DEFAULT false,ADD COLUMN superseded_by uuid REFERENCES noctis_v2.observations(id);
ALTER TABLE noctis_v2.analyses DROP CONSTRAINT analyses_pkey;
ALTER TABLE noctis_v2.analyses ADD COLUMN stage text NOT NULL DEFAULT 'parse', ADD COLUMN input_revision text NOT NULL DEFAULT '', ADD COLUMN schema_version text NOT NULL DEFAULT '1';
UPDATE noctis_v2.analyses a SET input_revision=o.revision FROM noctis_v2.observations o WHERE o.id=a.observation_id;
ALTER TABLE noctis_v2.analyses ADD PRIMARY KEY(stage,observation_id,input_revision,policy_version,schema_version);
CREATE TABLE noctis_v2.case_memberships(case_id uuid NOT NULL REFERENCES noctis_v2.intelligence_cases(id), observation_id uuid NOT NULL REFERENCES noctis_v2.observations(id), created_at timestamptz NOT NULL DEFAULT clock_timestamp(), PRIMARY KEY(case_id,observation_id));
INSERT INTO noctis_v2.case_memberships(case_id,observation_id) SELECT case_id,observation_id FROM noctis_v2.case_changes;
CREATE TABLE noctis_v2.case_group_conflicts(observation_id uuid PRIMARY KEY REFERENCES noctis_v2.observations(id), native_case uuid NOT NULL REFERENCES noctis_v2.intelligence_cases(id), content_case uuid NOT NULL REFERENCES noctis_v2.intelligence_cases(id), created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE INDEX memberships_case ON noctis_v2.case_memberships(case_id);
ALTER TABLE noctis_v2.case_changes DROP CONSTRAINT case_changes_observation_id_key;
ALTER TABLE noctis_v2.case_changes ADD COLUMN material_key text;
UPDATE noctis_v2.case_changes SET material_key='observation:'||observation_id::text;
ALTER TABLE noctis_v2.case_changes ALTER COLUMN material_key SET NOT NULL;
ALTER TABLE noctis_v2.case_changes ADD UNIQUE(material_key);
CREATE TABLE noctis_v2.analysis_results(job_id uuid PRIMARY KEY REFERENCES noctis_v2.jobs(id), digest text NOT NULL, body jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE noctis_v2.claim_versions(id uuid NOT NULL, revision integer NOT NULL CHECK(revision>0), case_id uuid NOT NULL REFERENCES noctis_v2.intelligence_cases(id), subject text NOT NULL, predicate text NOT NULL, object text NOT NULL, status text NOT NULL CHECK(status IN ('source_claim','supported','contradicted','unresolved','retracted')), producer text NOT NULL, policy_version text NOT NULL, evidence jsonb NOT NULL, reason text NOT NULL DEFAULT '', invalidated boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT clock_timestamp(), PRIMARY KEY(id,revision));
CREATE TABLE noctis_v2.claim_dependencies(claim_id uuid NOT NULL,claim_revision integer NOT NULL,dependency_id uuid NOT NULL,dependency_revision integer NOT NULL,relation text NOT NULL CHECK(relation IN ('supports','contradicts','depends_on')),PRIMARY KEY(claim_id,claim_revision,dependency_id,dependency_revision,relation),FOREIGN KEY(claim_id,claim_revision) REFERENCES noctis_v2.claim_versions(id,revision),FOREIGN KEY(dependency_id,dependency_revision) REFERENCES noctis_v2.claim_versions(id,revision));
ALTER TABLE noctis_v2.briefs ADD COLUMN invalidated boolean NOT NULL DEFAULT false;
CREATE TABLE noctis_v2.entities(id uuid PRIMARY KEY,kind text NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE noctis_v2.entity_aliases(id uuid PRIMARY KEY,entity_id uuid NOT NULL REFERENCES noctis_v2.entities(id),alias text NOT NULL,scope text NOT NULL,language text NOT NULL,evidence jsonb NOT NULL,revoked boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE noctis_v2.entity_hypotheses(id uuid PRIMARY KEY,left_id uuid NOT NULL REFERENCES noctis_v2.entities(id),right_id uuid NOT NULL REFERENCES noctis_v2.entities(id),relation text NOT NULL,evidence jsonb NOT NULL,status text NOT NULL CHECK(status IN ('unresolved','retracted')),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),CHECK(left_id<>right_id));
CREATE TABLE noctis_v2.source_imports(manifest_id text PRIMARY KEY,digest text NOT NULL,manifest jsonb NOT NULL,receipt jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE noctis_v2.source_dispositions(identity text PRIMARY KEY,source_id uuid REFERENCES noctis_v2.sources(id),body jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE noctis_v2.legacy_records(archive_digest text NOT NULL,table_name text NOT NULL,legacy_id text NOT NULL,source_id uuid NOT NULL REFERENCES noctis_v2.sources(id),body jsonb NOT NULL,PRIMARY KEY(archive_digest,table_name,legacy_id));
CREATE TABLE noctis_v2.telegram_accounts(id text PRIMARY KEY,auth_generation uuid NOT NULL,state jsonb NOT NULL DEFAULT '{"pts":0,"qts":0,"date":0,"seq":0}',owner text,owner_fence bigint NOT NULL DEFAULT 0,lease_expires_at timestamptz,closed boolean NOT NULL DEFAULT true,status text NOT NULL DEFAULT 'paused',retry_at timestamptz,gap boolean NOT NULL DEFAULT true,updated_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE noctis_v2.telegram_peers(account_id text NOT NULL REFERENCES noctis_v2.telegram_accounts(id),peer_type text NOT NULL CHECK(peer_type IN ('user','chat','channel')),peer_id bigint NOT NULL,source_id uuid NOT NULL UNIQUE REFERENCES noctis_v2.sources(id),auth_generation uuid NOT NULL,access_hash bigint,allowed boolean NOT NULL DEFAULT false,pts integer NOT NULL DEFAULT 0,PRIMARY KEY(account_id,peer_type,peer_id));
CREATE TABLE noctis_v2.telegram_inbox(account_id text NOT NULL REFERENCES noctis_v2.telegram_accounts(id),peer_type text NOT NULL,peer_id bigint NOT NULL,message_id integer NOT NULL,revision text NOT NULL,event text NOT NULL,disposition text NOT NULL,metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(account_id,peer_type,peer_id,message_id,revision));
CREATE TABLE noctis_v2.telegram_commits(account_id text NOT NULL REFERENCES noctis_v2.telegram_accounts(id),batch_id uuid NOT NULL,digest text NOT NULL,receipt jsonb NOT NULL,PRIMARY KEY(account_id,batch_id));
CREATE TABLE noctis_v2.telegram_channel_states(account_id text NOT NULL REFERENCES noctis_v2.telegram_accounts(id),channel_id bigint NOT NULL,pts integer NOT NULL,PRIMARY KEY(account_id,channel_id));
ALTER TABLE noctis_v2.telegram_peers ADD COLUMN bootstrap_epoch uuid NOT NULL DEFAULT gen_random_uuid();
CREATE TABLE noctis_v2.telegram_history_cursors(source_id uuid NOT NULL REFERENCES noctis_v2.sources(id),epoch uuid NOT NULL,offset_id integer NOT NULL,complete boolean NOT NULL DEFAULT false,PRIMARY KEY(source_id,epoch));
CREATE TABLE noctis_v2.feed_snapshots(id uuid PRIMARY KEY,kind text NOT NULL,url text NOT NULL,hash text NOT NULL,as_of timestamptz NOT NULL,expires_at timestamptz NOT NULL,collected_at timestamptz NOT NULL DEFAULT clock_timestamp(),payload jsonb NOT NULL,UNIQUE(kind,url,hash));
CREATE TABLE noctis_v2.feed_cursors(kind text NOT NULL,url text NOT NULL,cursor jsonb NOT NULL,snapshot_id uuid NOT NULL REFERENCES noctis_v2.feed_snapshots(id),PRIMARY KEY(kind,url));
CREATE TABLE noctis_v2.vulnerability_facts(snapshot_id uuid NOT NULL REFERENCES noctis_v2.feed_snapshots(id),cve text NOT NULL,body jsonb NOT NULL,applicability text NOT NULL DEFAULT 'unknown' CHECK(applicability='unknown'),PRIMARY KEY(snapshot_id,cve));
CREATE INDEX vulnerability_cve ON noctis_v2.vulnerability_facts(cve);
CREATE TABLE noctis_v2.enrichment_policies(provider text PRIMARY KEY,version text NOT NULL,enabled boolean NOT NULL DEFAULT false,data_classes jsonb NOT NULL,quota_per_day integer NOT NULL CHECK(quota_per_day>=0),ttl_seconds integer NOT NULL CHECK(ttl_seconds>0 AND ttl_seconds<=604800));
CREATE TABLE noctis_v2.enrichment_policy_revisions(provider text NOT NULL,version text NOT NULL,body jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(provider,version));
CREATE TABLE noctis_v2.enrichment_usage(provider text NOT NULL REFERENCES noctis_v2.enrichment_policies(provider),day date NOT NULL,used integer NOT NULL DEFAULT 0,PRIMARY KEY(provider,day));
CREATE TABLE noctis_v2.enrichment_attempts(id uuid PRIMARY KEY,provider text NOT NULL,policy_version text NOT NULL,observable_type text NOT NULL,value text NOT NULL,data_class text NOT NULL,state text NOT NULL CHECK(state IN ('reserved','succeeded','failed','uncertain')),created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE noctis_v2.enrichment_cache(provider text NOT NULL,policy_version text NOT NULL,observable_type text NOT NULL,value text NOT NULL,data_class text NOT NULL,body jsonb NOT NULL,observed_at timestamptz NOT NULL,expires_at timestamptz NOT NULL,PRIMARY KEY(provider,policy_version,observable_type,value,data_class));
CREATE TABLE noctis_v2.observable_sightings(observable_type text NOT NULL,value text NOT NULL,observation_id uuid NOT NULL REFERENCES noctis_v2.observations(id),revision text NOT NULL,start_byte integer NOT NULL,end_byte integer NOT NULL,evidence jsonb NOT NULL,PRIMARY KEY(observable_type,value,observation_id,revision,start_byte,end_byte));
CREATE TABLE noctis_v2.indicator_versions(id uuid NOT NULL,revision integer NOT NULL CHECK(revision>0),observable_type text NOT NULL,value text NOT NULL,scope text NOT NULL,status text NOT NULL CHECK(status IN ('active','revoked')),valid_from timestamptz NOT NULL,valid_until timestamptz NOT NULL,policy_version text NOT NULL,producer text NOT NULL,reason text NOT NULL,evidence jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(id,revision),CHECK(valid_until>valid_from));
CREATE TABLE noctis_v2.asset_versions(id uuid NOT NULL,revision integer NOT NULL CHECK(revision>0),cpe text NOT NULL,version text,evidence jsonb NOT NULL,producer text NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(id,revision));
CREATE TABLE noctis_v2.local_applicability(snapshot_id uuid NOT NULL,cve text NOT NULL,asset_id uuid NOT NULL,asset_revision integer NOT NULL,status text NOT NULL CHECK(status IN ('affected_version','not_affected_version','unknown')),reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(snapshot_id,cve,asset_id,asset_revision),FOREIGN KEY(snapshot_id,cve) REFERENCES noctis_v2.vulnerability_facts(snapshot_id,cve),FOREIGN KEY(asset_id,asset_revision) REFERENCES noctis_v2.asset_versions(id,revision));
